package workspaces

import (
	"time"

	tea "github.com/charmbracelet/bubbletea"

	"github.com/anthnel/devdesk/internal/cache"
	"github.com/anthnel/devdesk/internal/config"
	"github.com/anthnel/devdesk/internal/credentials"
	"github.com/anthnel/devdesk/internal/jobs"
	"github.com/anthnel/devdesk/internal/scan"
	sharedcomponents "github.com/anthnel/devdesk/internal/ui/components"
	"github.com/anthnel/devdesk/internal/ui/datatable"
)

// ViewMode represents the current mode of the view
type ViewMode int

const (
	ModeNormal ViewMode = iota
	ModeAdding
	ModeConfirmingDelete
	ModeRenaming
	ModeSelecting         // Selecting a directory for another view (e.g., security)
	ModeConfirmingScanAll // A asked to scan everything; the modal carries the purge option
)

// Model represents the Workspaces view's model
type Model struct {
	config *config.Config
	width  int
	height int

	table datatable.Model[workspaceRow]
	error string

	// Navigation state (drill-down like explorer)
	currentPath string // Empty = root (workspaces list), otherwise = current directory path
	// listingPath is the directory the rows currently in the table were read
	// from. It equals currentPath exactly when the table shows where the view
	// says it is; between a navigation and the load landing, it does not — and
	// that difference is the one thing that says "these rows are not this
	// directory's".
	listingPath     string
	navigationStack []string // Stack of parent paths for breadcrumb tabs
	cursorStack     []int    // Cursor positions per level for restoration on navigate-up
	pendingCursor   int      // Cursor to restore after async loadEntries (-1 = none)

	// Tab navigation
	activeTabIndex int

	// Mode and components
	mode         ViewMode
	input        *WorkspaceInput
	confirmModal *sharedcomponents.ConfirmModal
	// scanAllModal carries A's purge checkbox. Separate from confirmModal
	// because the two answer different messages, and one field holding either
	// would make the handler guess which question was asked.
	scanAllModal *sharedcomponents.OptionConfirmModal
	// pendingEntry is what the open modal or rename form is about. It holds the
	// entry rather than its row index: the index meant nothing once the list it
	// indexed stopped being the list on screen (D24).
	pendingEntry *Entry

	// Scan cache: keyed by absolute repo path
	scanCache map[string]cache.WorkspaceScanEntry

	// pendingRequests holds what an agent asked for before this view had read
	// the directory (§3.61). Building a view is not filling it, and a request
	// served against an empty model would refuse with a sentence about the disk
	// that is not true of it.
	pendingRequests []tea.Msg

	// jobs is the router's snapshot of everything running anywhere, and
	// jobFrame the spinner frame that goes with it — bare, because it lands in
	// a table cell (Rule 122). Together they replaced three maps of paths, a
	// spinner.Model, a hand-stamped frame index and the syncRun that counted a
	// batch alongside them.
	//
	// The three maps knew only what this view had started, which is why a scan
	// launched on the same repository from `:sec` slipped past busy(). See
	// jobs.go.
	jobs     []jobs.Run
	jobFrame string

	// syncUnreadable counts the directories the walk behind the current sync
	// could not read. It is not a sync outcome — a repository under one of them
	// was never a target — so it has no item in the run, and it is remembered
	// here until the summary is written.
	syncUnreadable int

	// secrets is the context's secret store, the one the router resolved. A
	// sync fetches, and a fetch against the configured GitLab needs the token —
	// with the credential helper shut out, it is the only way in (§3.16).
	secrets credentials.Storage

	// footer is the one line of transient state below the viewport (Rule 128).
	footer sharedcomponents.FooterMessage

	// selectionMessage is displayed in the footer when in ModeSelecting
	selectionMessage string

	// deps is where the scanners resolve from on this machine, or nil while
	// nobody has looked yet. A pointer because "not yet known" and "neither
	// scanner is installed" are different answers, and a zero DependencyStatus
	// says the second — the *bool of Result.SecretVerdict, one screen over.
	//
	// It is read by actions() to decide whether S and A apply at all, and it is
	// filled by a Cmd: scan.CheckDependencies runs exec.LookPath, a --version
	// and a docker images -q, none of which may happen in New or View
	// (Rule 110).
	deps *scan.DependencyStatus
}

// Entry represents a file system entry with enriched metadata
type Entry struct {
	Name    string
	Path    string
	ModTime time.Time
	IsDir   bool

	// Git metadata (populated only for git repos)
	IsGitRepo    bool
	SubRepoPaths []string // git repos nested within this directory (if !IsGitRepo)
	// SubRepoSkipped counts the directories the walk could not read or resolve.
	// Without it the footer could say how many repositories were about to be
	// scanned and nothing at all about how many it had failed to look for,
	// which is what made D59 silent rather than merely annoying.
	SubRepoSkipped int
	GitBranch      string
	GitRemote      string // remote path without server URL (e.g. "group/project")
	GitRemoteURL   string // full remote URL normalized for browser opening
	GitModified    int
	GitUntracked   int
	GitUnpushed    int
	GitUnpulled    int
}

// New creates a new instance of the workspaces model.
//
// secrets may be nil for a view that will never sync — the borrowed selection
// mode is the one such case — and a nil store simply means no token is offered.
func New(cfg *config.Config, secrets credentials.Storage) Model {
	return Model{
		config:  cfg,
		secrets: secrets,
		table: datatable.New(datatable.Config[workspaceRow]{
			Columns:    workspaceColumns(cfg.Scan.EnableCIScore),
			SortColumn: -1, // the order the directory listing gave
		}),
		mode:          ModeNormal,
		pendingCursor: -1,
		scanCache:     make(map[string]cache.WorkspaceScanEntry),
	}
}

// NewForSelection creates a workspaces view in selection mode for picking a
// directory. It is lent to another view to answer one question and never syncs,
// so it carries no secret store.
func NewForSelection(cfg *config.Config, message string) Model {
	m := New(cfg, nil)
	m.mode = ModeSelecting
	m.selectionMessage = message
	return m
}

package workspaces

import (
	"log"
	"os"
	"path/filepath"
	"strings"

	"github.com/anthnel/devdesk/internal/git"
)

// isHidden decides what the workspaces view leaves out.
//
// One rule, consulted by the listing and by the nested-repo walk both: what the
// view shows is what S and F act on, and two rules for that question would let
// a repository be a visible row and an invisible target at once.
//
// The consequence of showHidden is worth stating rather than discovering: the
// walk will then descend into .venv, .terraform and .cache, so S on a directory
// reaches whatever they vendor. What bounds the walk is not a depth limit — see
// walkSubRepos — but the fact that it stops at every repository it finds.
func isHidden(name string, showHidden bool) bool {
	return !showHidden && strings.HasPrefix(name, ".")
}

// enrichEntry populates git and project type metadata for a directory entry
func enrichEntry(entry *Entry, showHidden bool) {
	detectGitStatus(entry)
	if entry.IsGitRepo {
		return
	}
	// For non-git directories, find every nested git repo, however deep.
	found := detectSubRepos(entry.Path, showHidden)
	entry.SubRepoPaths = found.Repos
	entry.SubRepoSkipped = found.Skipped
}

// detectGitStatus populates git-related fields on the entry.
//
// The reading itself is git.ReadStatus: this file used to run the four commands
// with its own execGit while internal/git counted the divergence again for the
// sync, and the MCP server (§3.38) needed the same answers a third time. What
// stays here is the part that is a *display* decision — turning `origin` into
// something a user reads and something a browser opens — because that is what
// the view owns and the domain package deliberately does not.
//
// GitUnpulled is as fresh as the last fetch, and nothing here fetches (D35).
func detectGitStatus(entry *Entry) {
	if !isRepo(entry.Path) {
		return
	}
	entry.IsGitRepo = true

	status, err := git.ReadStatus(entry.Path)
	if err != nil {
		return
	}

	entry.GitBranch = status.Branch
	entry.GitModified = status.Modified
	entry.GitUntracked = status.Untracked
	entry.GitUnpushed = status.Ahead
	entry.GitUnpulled = status.Behind

	if status.Remote != "" {
		entry.GitRemote = extractRemotePath(status.Remote)
		entry.GitRemoteURL = normalizeRemoteURL(status.Remote)
	}
}

// extractRemotePath strips the server from a git remote URL and returns only the path.
// Examples:
//
//	"https://gitlab.com/group/project.git" → "group/project"
//	"git@gitlab.com:group/project.git"     → "group/project"
func extractRemotePath(rawURL string) string {
	// SCP-like syntax: git@host:path — colon must not be followed by "//"
	if idx := strings.Index(rawURL, ":"); idx != -1 && !strings.Contains(rawURL[:idx], "/") {
		after := rawURL[idx+1:]
		if !strings.HasPrefix(after, "//") {
			return strings.TrimSuffix(after, ".git")
		}
	}
	// URL syntax: scheme://host/path
	if idx := strings.Index(rawURL, "://"); idx != -1 {
		rest := rawURL[idx+3:]
		if slash := strings.Index(rest, "/"); slash != -1 {
			return strings.TrimSuffix(rest[slash+1:], ".git")
		}
	}
	return rawURL
}

// normalizeRemoteURL delegates to internal/git, which owns the rule since
// §3.42 needed the same host comparison from a domain package.
func normalizeRemoteURL(rawURL string) string {
	return git.NormalizeRemoteURL(rawURL)
}

// subRepoScan is what a walk found, and what it could not look at.
//
// Skipped is the second half, and it is the one that decides whether a gap is
// visible: a scan that silently leaves work out is the whole of D59, and the
// footer had no number for it. A directory refused by the filesystem is not an
// error the user can act on from here, but "12 repositories, 3 directories I
// could not read" is a different sentence from "12 repositories".
type subRepoScan struct {
	Repos   []string
	Skipped int
}

// detectSubRepos returns the git repositories under basePath, at any depth,
// and how many directories the walk could not read.
//
// It used to stop at three levels, and that literal was D59: a repository at
// `monorepos/client/2026/api` was invisible to S, F and A while the directory
// holding it browsed normally, and nothing on screen said a limit had been
// applied. A scan that silently leaves work out is worse than a slow one, so
// there is no limit any more.
//
// What bounds the walk instead, and why it is enough:
//
//   - It stops at every repository it finds, so a repository's own node_modules
//     or vendor tree is never entered. That is the prune that matters, and it
//     was always the one doing the work.
//   - It refuses to enter a link pointing back up the path it came by, and to
//     enter the same tree through a second link. That is the cycle guard the
//     depth limit used to provide by accident, and it is what makes following
//     links safe at all.
//
// Measured before removing the limit, on this machine: over ~/projects the
// unbounded walk was as fast or faster than the bounded one (the repositories
// are shallow, so both stop at the same places), and over the Go module cache —
// tens of thousands of directories with no repository anywhere to prune it — it
// took 283 ms against 37 ms. That is the worst case, it runs in a Cmd rather
// than in Update, and it is the price of not losing repositories.
func detectSubRepos(basePath string, showHidden bool) subRepoScan {
	var found subRepoScan
	var crossed []os.FileInfo
	walkSubRepos(basePath, showHidden, &crossed, &found)
	return found
}

// walkSubRepos is the recursive helper for detectSubRepos.
func walkSubRepos(dir string, showHidden bool, crossed *[]os.FileInfo, found *subRepoScan) {
	entries, err := os.ReadDir(dir)
	if err != nil {
		// Swallowed until now: a directory refused in the middle of a tree
		// contributed nothing and said nothing, which is the same silence the
		// depth limit was (§1.3 D59).
		log.Printf("ERROR [workspaces] read %s: %v", dir, err)
		found.Skipped++
		return
	}

	// Read out of the listing rather than asked for with os.Stat, and the
	// difference is not small. Recognising a bare repository needs three names
	// where `.git` needed one, and a failed stat apiece is what that costs on
	// Windows: measured over the Go module cache — the worst case, tens of
	// thousands of directories with no repository anywhere to prune the walk —
	// the stat version took 334 ms against the old walk's 75 ms. The listing is
	// already being fetched, so the same question costs nothing here, and the
	// walk now runs it in 65 ms while finding strictly more. The price is one
	// ReadDir on a repository's own root, and repositories are where it stops.
	if holdsRepo(entries) {
		found.Repos = append(found.Repos, dir)
		return // don't recurse into nested repos
	}
	for _, e := range entries {
		if isHidden(e.Name(), showHidden) {
			continue
		}
		child := filepath.Join(dir, e.Name())

		// A real directory cannot close a cycle on its own, so it is entered
		// without asking. Only a link can, and only a link pays for the check.
		if e.IsDir() {
			walkSubRepos(child, showHidden, crossed, found)
			continue
		}
		if !leadsToDir(e, child) {
			continue
		}
		follow, err := mayFollow(child, crossed)
		if err != nil {
			log.Printf("ERROR [workspaces] resolve %s: %v", child, err)
			found.Skipped++
			continue
		}
		if !follow {
			continue
		}
		walkSubRepos(child, showHidden, crossed, found)
	}
}

// mayFollow decides whether a link may be entered, and records it when it may.
//
// Identity is os.SameFile rather than a resolved path, and that is not a
// preference: filepath.EvalSymlinks does **not** resolve a Windows junction —
// it hands back the link's own path — so a resolved-path guard sees two
// different names for one directory and never fires. Measured here on a
// junction: Readlink answers, EvalSymlinks does not, SameFile does. And a
// junction is exactly what the defect was reported against.
//
// Two questions, and they are different:
//
//   - **Pointing back up the path we came by.** Entering it walks the same tree
//     again, and again. Every directory the walk crossed is a prefix of the
//     link's own path, so the chain costs nothing to reconstruct — and the
//     climb goes to the filesystem root rather than to the base, because a link
//     above the base drags the base back in with it.
//   - **Already entered through another link.** That is not a loop but a
//     duplicate: the same repositories under a second name, and a second scan
//     of each.
//
// Only a link pays for any of this. A tree with none in it makes no extra call.
func mayFollow(link string, crossed *[]os.FileInfo) (bool, error) {
	target, err := os.Stat(link)
	if err != nil {
		return false, err
	}

	for dir := filepath.Dir(link); ; {
		if info, err := os.Stat(dir); err == nil && os.SameFile(info, target) {
			return false, nil
		}
		parent := filepath.Dir(dir)
		if parent == dir {
			break
		}
		dir = parent
	}

	for _, seen := range *crossed {
		if os.SameFile(seen, target) {
			return false, nil
		}
	}
	*crossed = append(*crossed, target)
	return true, nil
}

// leadsToDir reports whether a listing entry leads to a directory, following a
// symbolic link or a Windows junction to answer.
//
// DirEntry.IsDir() reports on the link itself, so it said false for a junction
// pointing at a directory full of repositories: everything behind it was
// invisible to S, F and A, and the row rendered as a file — neither browsable
// nor scannable, with nothing saying why (§1.3 D59, cause 2).
//
//	entry a         IsDir=true   type=d---------  statIsDir=true
//	entry linked    IsDir=false  type=?---------  statIsDir=true   ← ignored
//
// The test is "not a plain file" rather than "is a symlink" on purpose: Go has
// reported a Windows junction as ModeSymlink and as ModeIrregular depending on
// the version, and os.Stat answers the same either way. A regular file costs no
// syscall, which is what keeps this affordable on a tree with no links in it.
func leadsToDir(e os.DirEntry, path string) bool {
	if e.IsDir() {
		return true
	}
	if e.Type().IsRegular() {
		return false
	}
	info, err := os.Stat(path)
	return err == nil && info.IsDir()
}

// isRepo reports whether dir is a git repository, from its own listing.
//
// One rule, one implementation: walkSubRepos asks holdsRepo directly because it
// has the listing in hand, and this is the entry point for a single directory —
// the row detectGitStatus is enriching. Its one ReadDir is nothing beside the
// four git subprocesses ReadStatus runs immediately after.
func isRepo(dir string) bool {
	entries, err := os.ReadDir(dir)
	if err != nil {
		return false
	}
	return holdsRepo(entries)
}

// holdsRepo is the rule: what a directory has to contain to be a repository.
//
// `.git` catches a working tree and a worktree alike — it is a directory in the
// first and a file in the second, and neither is asked about. What it misses is
// a *bare* repository, whose HEAD, objects and refs sit at the root: that one
// holds history, so it is a scan target like any other, and leaving it out was
// the same silent omission as the depth limit (§1.3 D59).
//
// All three are required for the bare case. A directory that merely has an
// `objects` in it is not a repository, and calling it one would send a scan
// somewhere there is nothing to read.
func holdsRepo(entries []os.DirEntry) bool {
	var head, objects, refs bool
	for _, e := range entries {
		switch e.Name() {
		case ".git":
			return true
		case "HEAD":
			head = true
		case "objects":
			objects = true
		case "refs":
			refs = true
		}
	}
	return head && objects && refs
}

package workspaces

import (
	"fmt"
	"log"
	"os"
	"path/filepath"

	tea "github.com/charmbracelet/bubbletea"

	"github.com/anthnel/devdesk/internal/jobs"
	sharedcomponents "github.com/anthnel/devdesk/internal/ui/components"
	"github.com/anthnel/devdesk/internal/ui/keymap"
)

// Init initializes the model
func (m Model) Init() tea.Cmd {
	cmds := []tea.Cmd{m.loadEntries(), loadScanCacheCmd()}
	// A view lent for a selection offers neither S nor A, so resolving the
	// scanners for it would be three subprocesses spawned to answer a question
	// nobody asks.
	if m.mode == ModeNormal {
		cmds = append(cmds, checkDepsCmd(m.config.Scan))
	}
	return tea.Batch(cmds...)
}

// InEditMode returns true if the view is in an edit mode (input, confirm, selection, or filter search)
func (m Model) InEditMode() bool {
	return m.mode != ModeNormal || m.table.InEditMode()
}

// FilterBarVisible returns true when the filter bar is visible (implements app.FilterBarView).
func (m Model) FilterBarVisible() bool {
	return m.table.FilterBar().IsVisible() && m.mode == ModeNormal && len(m.table.Items()) > 0 && m.error == ""
}

// Update handles messages
func (m Model) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
	var cmd tea.Cmd

	switch msg := msg.(type) {
	case tea.WindowSizeMsg:
		m.width = msg.Width
		m.height = msg.Height
		m.updateTableSize()

	case tea.KeyMsg:
		return m.handleKeyMsg(msg)

	case DepsCheckedMsg:
		deps := msg.Deps
		m.deps = &deps

	case EntriesLoadedMsg:
		// A listing of somewhere the user has already left: two loads were in
		// flight and this is the loser. Displaying it would put one directory's
		// rows under another's breadcrumb.
		if msg.Path != m.currentPath {
			return m, nil
		}
		m.listingPath = msg.Path
		m.setEntries(msg.Entries)
		m.error = ""
		m.refreshRows()
		if m.pendingCursor >= 0 {
			m.table.SetCursor(m.pendingCursor)
			m.pendingCursor = -1
		}
		// Anything an agent asked for before this view had read the directory
		// waited for exactly this (§3.61) — see deferUntilLoaded.
		if cmd := m.drainPendingRequests(); cmd != nil {
			return m, cmd
		}

	case LoadErrorMsg:
		if msg.Path != m.currentPath {
			return m, nil
		}
		m.error = msg.Error.Error()
		if cmd := m.refusePendingRequests("Cannot read " + msg.Path + ": " + msg.Error.Error()); cmd != nil {
			return m, cmd
		}

	case WorkspaceInputSubmitMsg:
		return m.handleInputSubmit(msg)

	case RenameInputSubmitMsg:
		return m.handleRenameSubmit(msg)

	case WorkspaceInputCancelMsg:
		m.mode = ModeNormal
		m.input = nil
		return m, nil

	case WorkspaceCreatedMsg:
		return m.handleWorkspaceCreated(msg)

	case EntryDeletedMsg:
		return m.handleEntryDeleted(msg)

	case EntryRenamedMsg:
		return m.handleEntryRenamed(msg)

	case sharedcomponents.ConfirmModalYesMsg:
		return m.handleConfirmDelete()

	case sharedcomponents.ConfirmModalNoMsg:
		m.mode = ModeNormal
		m.confirmModal = nil
		return m, nil

	case sharedcomponents.OptionConfirmModalYesMsg:
		m.mode = ModeNormal
		m.scanAllModal = nil
		return m.scanAll(msg.Option)

	case sharedcomponents.OptionConfirmModalNoMsg:
		m.mode = ModeNormal
		m.scanAllModal = nil
		return m, nil

	case TerminalExitMsg:
		return m, m.loadEntries()

	case TerminalOpenedMsg:
		return m.handleTerminalOpened(msg)

	case IDEOpenedMsg:
		if msg.Error != nil {
			m.error = msg.Error.Error()
		}
		return m, nil

	case BrowserOpenedMsg:
		if msg.Error != nil {
			m.error = msg.Error.Error()
		}
		return m, nil

	case PathCopiedMsg:
		return m.handlePathCopied(msg)

	case jobs.ChangedMsg:
		return m.handleJobsChanged(msg)

	case ScanCacheLoadedMsg:
		if msg.Cache != nil {
			m.scanCache = msg.Cache
			m.refreshRows()
		}
		return m, nil

	case ScanRequestMsg:
		return m.handleScanRequest(msg)

	// An agent asks the way a key does (§3.61) — see mcp.go.
	case ScanRequestedMsg:
		return m.handleScanRequested(msg)

	case SyncRequestedMsg:
		return m.handleSyncRequested(msg)

	case WorkspaceScanStartingMsg:
		// The row is already spinning: the router recorded the transition
		// before handing the message on, and the snapshot that carried it
		// rebuilt the rows. All that is left is to drop whatever the footer
		// still said about the previous attempt.
		m.footer.Clear()
		return m, nil

	case WorkspaceScanCompleteMsg:
		return m.handleWorkspaceScanComplete(msg)

	case WorkspaceSyncStartingMsg:
		m.footer.Clear()
		return m, nil

	case WorkspaceSyncCompleteMsg:
		return m.handleWorkspaceSyncComplete(msg)

	}

	m.footer.Handle(msg)

	// Update table only in normal mode
	if m.mode == ModeNormal {
		cmd = m.table.Update(msg)
	}

	return m, cmd
}

// handleKeyMsg handles keyboard input
func (m Model) handleKeyMsg(msg tea.KeyMsg) (tea.Model, tea.Cmd) {
	// Filter bar search mode - delegate to filter bar
	if m.table.InEditMode() {
		return m, m.table.Update(msg)
	}

	// Mode input - delegate to input component
	if m.mode == ModeAdding && m.input != nil {
		var cmd tea.Cmd
		m.input, cmd = m.input.Update(msg)
		return m, cmd
	}

	// Mode confirm - delegate to confirm modal
	if m.mode == ModeConfirmingDelete && m.confirmModal != nil {
		var cmd tea.Cmd
		m.confirmModal, cmd = m.confirmModal.Update(msg)
		return m, cmd
	}

	// Mode scan-all - delegate to the option modal
	if m.mode == ModeConfirmingScanAll && m.scanAllModal != nil {
		var cmd tea.Cmd
		m.scanAllModal, cmd = m.scanAllModal.Update(msg)
		return m, cmd
	}

	// Mode renaming - delegate to input component
	if m.mode == ModeRenaming && m.input != nil {
		var cmd tea.Cmd
		m.input, cmd = m.input.Update(msg)
		return m, cmd
	}

	// Selection mode - pick a directory for security view
	if m.mode == ModeSelecting {
		return m.handleSelectionKeyMsg(msg)
	}

	// Normal mode. The actions the header greys out are refused here, from the
	// same actionSet — one calculation, two readers, so a greyed key that still
	// acts is not expressible.
	a := m.actions()

	switch msg.String() {
	case "/":
		return m, m.table.Update(msg)
	case "enter":
		return m.guard(a.Enter, m.openScanDetails)
	case "ctrl+r":
		return m, m.loadEntries()
	case keymap.New:
		return m.startAdd()
	case keymap.Rename:
		return m.guard(a.Rename, m.startRename)
	case keymap.Delete:
		return m.guard(a.Delete, m.startDelete)
	// The "new window" variant is a setting, not a second key: the capability
	// depends on the environment — the help already says it does not exist
	// under WSL, and through SSH there is no window to open (§3.26).
	case keymap.Terminal:
		return m.openTerminal()
	case keymap.IDE:
		return m.openIDE()
	case keymap.Web:
		return m.guard(a.Web, m.openInBrowser)
	case keymap.Scan:
		return m.guard(a.Scan, m.startSecurityScan)
	case keymap.Fetch:
		return m.guard(a.Sync, m.startSync)
	case keymap.ScanAll:
		return m.guard(a.All, m.confirmScanAll)
	case keymap.Copy:
		return m.guard(a.Copy, m.copyPath)
	case "left":
		return m.navigateUp()
	case "right":
		return m.navigateIn()
	case "esc":
		return m.navigateUp()
	case "up", "down", "pgup", "pgdown", "home", "end":
		return m, m.table.Update(msg)
	}

	return m, nil
}

// handlePathCopied reports the clipboard write (Rule 128).
//
// The confirmation says "full path" rather than repeating the entry's name: the
// row is under the cursor, so naming it again would be the same fact twice on
// one screen. What is not on screen is the *form* of what landed — the absolute
// path, not the name — and that is what the line says.
func (m Model) handlePathCopied(msg PathCopiedMsg) (tea.Model, tea.Cmd) {
	if msg.Error != nil {
		log.Printf("ERROR [workspaces] copy path %s to clipboard: %v", msg.Path, msg.Error)
		return m, m.footer.Error("Failed to copy the path — check logs")
	}
	return m, m.footer.Info("Full path copied to the clipboard")
}

// tabCount returns the total number of tabs (home + navigation stack entries + current)
func (m Model) tabCount() int {
	count := 1 // home tab
	count += len(m.navigationStack)
	if m.currentPath != "" {
		count++ // current directory tab
	}
	return count
}

// navigateIn enters the selected directory.
//
// It does nothing while the table still holds the previous directory's rows.
// A load is a Cmd, so holding `→` used to drill twice from one listing: the
// second press read the same row, pushed the *new* currentPath onto the stack,
// and the breadcrumb grew a duplicate — `devsecops devsecops devex devex`. With
// the cursor moved in between it was worse than duplication: a sibling of the
// directory just entered was pushed as if it were nested inside it.
//
// Refusing is the honest answer rather than a hazard to remember: the rows in
// hand are not this directory's, so there is nothing here to enter yet. `←` is
// deliberately not guarded — it reads the stack, not the table, and a listing
// it overtakes is dropped on arrival.
func (m Model) navigateIn() (tea.Model, tea.Cmd) {
	if m.listingPath != m.currentPath {
		return m, nil
	}

	entry, ok := m.selectedEntry()
	if !ok || !entry.IsDir {
		return m, nil
	}

	// Save cursor position before navigating down
	m.cursorStack = append(m.cursorStack, m.table.Cursor())
	// Push current path onto navigation stack
	if m.currentPath != "" {
		m.navigationStack = append(m.navigationStack, m.currentPath)
	}
	m.currentPath = entry.Path
	m.activeTabIndex = m.tabCount() - 1
	m.pendingCursor = -1
	return m, m.loadEntries()
}

// navigateUp goes to the parent directory
func (m Model) navigateUp() (tea.Model, tea.Cmd) {
	if m.currentPath == "" {
		return m, nil
	}

	if len(m.navigationStack) > 0 {
		// Pop from stack
		m.currentPath = m.navigationStack[len(m.navigationStack)-1]
		m.navigationStack = m.navigationStack[:len(m.navigationStack)-1]
	} else {
		// Go back to root
		m.currentPath = ""
	}

	// Restore cursor position at the parent level after entries load
	if len(m.cursorStack) > 0 {
		m.pendingCursor = m.cursorStack[len(m.cursorStack)-1]
		m.cursorStack = m.cursorStack[:len(m.cursorStack)-1]
	} else {
		m.pendingCursor = -1
	}

	m.activeTabIndex = m.tabCount() - 1
	return m, m.loadEntries()
}

// handleSelectionKeyMsg handles keyboard input in selection mode
func (m Model) handleSelectionKeyMsg(msg tea.KeyMsg) (tea.Model, tea.Cmd) {
	switch msg.String() {
	case "esc":
		if m.currentPath != "" {
			return m.navigateUp()
		}
		return m, func() tea.Msg { return SelectionCancelledMsg{} }
	case "enter":
		// Confirm selection: use the current browsing directory (not the highlighted entry).
		// Use → to navigate into a subdirectory first.
		path := m.currentPath
		if path == "" {
			path = m.getExpandedWorkspacesDir()
		}
		return m, func() tea.Msg { return DirectorySelectedMsg{Path: path} }
	case "left":
		return m.navigateUp()
	case "right":
		return m.navigateIn()
	case "up", "down", "pgup", "pgdown", "home", "end":
		return m, m.table.Update(msg)
	}
	return m, nil
}

// getExpandedWorkspacesDir returns the workspaces directory with tilde expanded
func (m Model) getExpandedWorkspacesDir() string {
	workspacesDir := m.config.App.WorkspacesDir
	if len(workspacesDir) >= 2 && workspacesDir[:2] == "~/" {
		home, _ := os.UserHomeDir()
		workspacesDir = filepath.Join(home, workspacesDir[2:])
	}
	return workspacesDir
}

// startAdd switches to input mode for creating a new workspace/folder
func (m Model) startAdd() (tea.Model, tea.Cmd) {
	m.mode = ModeAdding
	m.input = NewWorkspaceInput()
	return m, nil
}

// startDelete switches to confirm mode for deleting an entry
func (m Model) startDelete() (tea.Model, tea.Cmd) {
	entry, ok := m.selectedEntry()
	if !ok {
		return m, nil
	}
	// Refused before the modal rather than after it: asking the question and
	// then declining the answer is the one order that wastes the user's time.
	if m.busy(entry.Path) {
		return m, m.footer.Warn(busyMessage)
	}

	m.pendingEntry = &entry
	m.mode = ModeConfirmingDelete

	var title string
	if entry.IsDir {
		title = "Delete Directory"
	} else {
		title = "Delete File"
	}

	m.confirmModal = sharedcomponents.NewConfirmModal(
		title,
		fmt.Sprintf("Are you sure you want to delete '%s'?\n\nThis will permanently delete it and all its contents.", entry.Name),
	)
	return m, nil
}

// startRename switches to rename mode for the selected entry
func (m Model) startRename() (tea.Model, tea.Cmd) {
	entry, ok := m.selectedEntry()
	if !ok {
		return m, nil
	}
	m.pendingEntry = &entry
	m.mode = ModeRenaming
	m.input = NewRenameInput(entry.Name)
	return m, nil
}

// handleRenameSubmit handles the rename form submission
func (m Model) handleRenameSubmit(msg RenameInputSubmitMsg) (tea.Model, tea.Cmd) {
	m.mode = ModeNormal
	m.input = nil
	if m.pendingEntry == nil {
		return m, nil
	}
	return m, m.renameEntry(m.pendingEntry.Path, msg.Name)
}

// renameEntry renames a filesystem entry
func (m Model) renameEntry(oldPath, newName string) tea.Cmd {
	newPath := filepath.Join(filepath.Dir(oldPath), newName)
	return func() tea.Msg {
		if err := os.Rename(oldPath, newPath); err != nil {
			return EntryRenamedMsg{Error: err}
		}
		return EntryRenamedMsg{OldPath: oldPath, NewPath: newPath}
	}
}

// handleEntryRenamed handles the result of entry renaming
func (m Model) handleEntryRenamed(msg EntryRenamedMsg) (tea.Model, tea.Cmd) {
	if msg.Error != nil {
		m.error = msg.Error.Error()
		return m, nil
	}
	return m, m.loadEntries()
}

// handleInputSubmit handles the workspace input form submission
func (m Model) handleInputSubmit(msg WorkspaceInputSubmitMsg) (tea.Model, tea.Cmd) {
	m.mode = ModeNormal
	m.input = nil
	return m, m.createWorkspace(msg.Name)
}

// handleConfirmDelete handles the confirmation of entry deletion
func (m Model) handleConfirmDelete() (tea.Model, tea.Cmd) {
	m.mode = ModeNormal
	m.confirmModal = nil

	if m.pendingEntry == nil {
		return m, nil
	}
	path := m.pendingEntry.Path
	// Checked again here, not only in startDelete: a batch sync marks its
	// repositories from a Cmd, so one can take this path while the
	// confirmation is on screen. This is where the irreversible call is
	// issued, so this is where the answer has to be current.
	if m.busy(path) {
		return m, m.footer.Warn(busyMessage)
	}

	m.footer.Clear()
	return m, jobs.Start(m.deleteRun(path), m.deleteEntry(path))
}

// handleWorkspaceCreated handles the result of workspace creation
func (m Model) handleWorkspaceCreated(msg WorkspaceCreatedMsg) (tea.Model, tea.Cmd) {
	if msg.Error != nil {
		m.error = msg.Error.Error()
		return m, nil
	}
	return m, m.loadEntries()
}

// handleEntryDeleted handles the result of entry deletion
func (m Model) handleEntryDeleted(msg EntryDeletedMsg) (tea.Model, tea.Cmd) {
	// The marker is the registry's now, and it is cleared on every outcome —
	// failures included — by the transition the router applied before this ran.
	// One left behind would hold the path against every other action for the
	// life of the view.
	if msg.Error != nil {
		log.Printf("ERROR [workspaces] delete %s: %v", msg.Path, msg.Error)
		m.error = msg.Error.Error()
		return m, nil
	}
	return m, m.loadEntries()
}

package workspaces

import (
	"fmt"
	"path/filepath"
	"strconv"
	"strings"
	"time"

	"github.com/charmbracelet/lipgloss"

	"github.com/anthnel/devdesk/internal/cache"
	"github.com/anthnel/devdesk/internal/git"
	sharedcomponents "github.com/anthnel/devdesk/internal/ui/components"
	"github.com/anthnel/devdesk/internal/ui/fileicon"
	"github.com/anthnel/devdesk/internal/ui/help"
	"github.com/anthnel/devdesk/internal/ui/keymap"
	"github.com/anthnel/devdesk/internal/ui/shortcut"
	"github.com/anthnel/devdesk/internal/ui/theme"
)

// The column widths, defaultColumns and calculateColumns used to live here.
// calculateColumns clamped Modified at 15 *after* handing it the remainder, so
// the columns overflowed the viewport by up to 34 at narrow widths — the shape
// datatable's TestTheWorkspacesLayoutFitsANarrowTerminal was written against.
// The widths are in columns.go now and the arithmetic is the solver's.

// View renders the view
func (m Model) View() string {
	// Mode input - show input form overlay
	if m.mode == ModeAdding && m.input != nil {
		return lipgloss.Place(
			m.width, m.height,
			lipgloss.Center, lipgloss.Center,
			m.input.View(),
			lipgloss.WithWhitespaceBackground(theme.ColorBackground),
		)
	}

	// Mode confirm - show confirm modal overlay
	if m.mode == ModeConfirmingDelete && m.confirmModal != nil {
		return lipgloss.Place(
			m.width, m.height,
			lipgloss.Center, lipgloss.Center,
			m.confirmModal.View(),
			lipgloss.WithWhitespaceBackground(theme.ColorBackground),
		)
	}

	// Mode scan-all - show the option modal overlay
	if m.mode == ModeConfirmingScanAll && m.scanAllModal != nil {
		return lipgloss.Place(
			m.width, m.height,
			lipgloss.Center, lipgloss.Center,
			m.scanAllModal.View(),
			lipgloss.WithWhitespaceBackground(theme.ColorBackground),
		)
	}

	// Mode renaming - show rename input overlay
	if m.mode == ModeRenaming && m.input != nil {
		return lipgloss.Place(
			m.width, m.height,
			lipgloss.Center, lipgloss.Center,
			m.input.View(),
			lipgloss.WithWhitespaceBackground(theme.ColorBackground),
		)
	}

	// Content style with left padding (for non-table states only)
	contentStyle := lipgloss.NewStyle().Background(theme.ColorBackground).PaddingLeft(1)

	// Normal mode
	if m.error != "" {
		errorStyle := lipgloss.NewStyle().Background(theme.ColorBackground).Foreground(theme.ColorError)
		return contentStyle.Render(errorStyle.Render(theme.IconError + " Error: " + m.error))
	}

	return m.renderTable()
}

// renderTable renders the table content
func (m Model) renderTable() string {
	return m.table.View()
}

// GetFooterHeight returns the footer height for this view (Rule 124).
func (m Model) GetFooterHeight() int {
	switch m.mode {
	case ModeSelecting:
		return 3 // tab bar + empty line + info line (mirrors RenderFooter in ModeSelecting)
	case ModeNormal:
		if len(m.table.Items()) > 0 && m.error == "" {
			// filter bar (when visible) + breadcrumb tab bar + empty line + info line
			return 3 + m.table.FilterBar().ExtraHeight()
		}
	}
	return 2 // empty line + info line
}

// RenderFooter returns the footer content rendered below the viewport (Rule 124).
func (m Model) RenderFooter(width int) string {
	if m.mode == ModeSelecting {
		infoLine := m.footer.View(width, sharedcomponents.Status{Text: m.selectionMessage})
		return m.renderTabBar() + "\n" + theme.EmptyLineBg(width) + "\n" + infoLine
	}
	if m.mode == ModeNormal && len(m.table.Items()) > 0 && m.error == "" {
		var parts []string
		if bar := m.table.FilterBar(); bar.IsVisible() {
			parts = append(parts, bar.View())
		}
		parts = append(parts, m.renderTabBar(), theme.EmptyLineBg(width), m.renderInfoLine(width))
		return strings.Join(parts, "\n")
	}
	// An empty listing, or one that failed to load, still gets its info line:
	// Rule 124 budgets one whatever it holds, and this branch used to render a
	// second blank line instead — so a footer message posted here was
	// swallowed. That is exactly where a refusal lands (Y on an empty listing
	// has nothing to copy), and a refusal nobody can read is worse than none.
	return theme.EmptyLineBg(width) + "\n" + m.renderInfoLine(width)
}

// renderInfoLine is the footer's one line of state.
//
// A sync's progress is read from the run rather than from footerInfo because a
// batch outlives the three seconds a footer message gets: a line set when the
// first repository started would clear while the tenth was still fetching. An
// error still wins over it — it is the thing that needs answering.
func (m Model) renderInfoLine(width int) string {
	return m.footer.View(width, sharedcomponents.Status{Text: m.jobsStatusLine(), Spinner: m.anyWorking()})
}

// renderTabBar renders the breadcrumb tab bar at the bottom of the viewport
func (m Model) renderTabBar() string {
	tabs := []theme.TabItem{{Label: theme.IconHome + " home"}}

	// Add navigation stack entries as tabs
	for _, path := range m.navigationStack {
		tabs = append(tabs, theme.TabItem{Label: theme.IconDirectory + " " + pathBaseName(path)})
	}

	// Add current directory as last tab (if not at root)
	if m.currentPath != "" {
		tabs = append(tabs, theme.TabItem{Label: theme.IconDirectory + " " + pathBaseName(m.currentPath)})
	}

	return theme.PadWithBg(theme.Bg(" ")+theme.RenderTabs(tabs, m.activeTabIndex), m.width)
}

// pathBaseName returns the last component of a filesystem path.
//
// It splits with filepath, not on "/". The paths here are the ones os.ReadDir
// and filepath.Join produced, so on Windows they are separated by backslashes —
// and a split on "/" alone found nothing to cut, leaving the breadcrumb reading
// `󰉋 C:\Users\anthoni\workspaces\anthnell  󰉋 C:\Users\anthoni\workspaces\anthnell\devsecops`
// instead of `󰉋 anthnell  󰉋 devsecops`. Three tabs of that overflow the line
// and say less than one word each would.
func pathBaseName(path string) string {
	if path == "" {
		return ""
	}
	return filepath.Base(path)
}

// formatGitStatus formats the git status column for a table row
func formatGitStatus(entry Entry) string {
	if entry.GitBranch == "" {
		if !entry.IsDir {
			return ""
		}
		return ""
	}

	var parts []string
	parts = append(parts, theme.IconGitBranch+" "+entry.GitBranch)

	if entry.GitModified > 0 {
		parts = append(parts, fmt.Sprintf("%s%d", theme.IconGitModified, entry.GitModified))
	}
	if entry.GitUntracked > 0 {
		parts = append(parts, fmt.Sprintf("%s%d", theme.IconGitUntracked, entry.GitUntracked))
	}
	if entry.GitUnpushed > 0 {
		parts = append(parts, fmt.Sprintf("%s%d", theme.IconGitUnpushed, entry.GitUnpushed))
	}
	if entry.GitUnpulled > 0 {
		parts = append(parts, fmt.Sprintf("%s%d", theme.IconGitUnpulled, entry.GitUnpulled))
	}

	return strings.Join(parts, " ")
}

// entryIcon is the glyph in the leftmost column: what this row *is*.
//
// It replaced a Type column that showed a *project* type — detectProjectType
// looked for go.mod or package.json and answered "this is a Go project", which
// is a different question and was judged not worth a column of its own.
//
// Three genres, and the first is the one that earns the column. Half the keys
// in this view act on IsGitRepo — S, F, A, D, enter — and Rule 130 shows or
// hides them accordingly, so the user watched the shortcuts change with nothing
// on the row saying why. Git Status betrays a repository only when it has a
// readable branch: one in detached HEAD, one that is empty, one git refuses to
// read all showed an empty cell and looked like any other directory.
//
// A directory holding *nested* repositories still reads as a plain directory.
// S, F and A act on it too, so a fourth glyph would be defensible; three is
// what was asked for, and the row already has no other way to say it either.
func entryIcon(entry Entry) string {
	switch {
	case entry.IsGitRepo:
		return theme.IconGitBranch
	case entry.IsDir:
		return theme.IconDirectory
	default:
		return fileicon.For(entry.Name)
	}
}

// entryIconRole colours the glyph above, and it splits the listing exactly
// where the row's *actions* split (availability.go): a repository can be
// scanned, synced and opened on its forge; a directory can be entered; a file
// can be read and nothing else.
//
// It is deliberately three roles and not one per file type. A per-language
// tint is what eza does, and it would be decoration here: what changes between
// two rows of this table is which shortcuts are lit, and `.go` versus `.rs`
// changes none of them. The colour says what the row *is for*.
func entryIconRole(entry Entry) theme.IconRole {
	switch {
	case entry.IsGitRepo:
		// The same role the explorer paints a forge repository with. One
		// colour for a repository across the three views that list one.
		return theme.IconRoleRepository
	case entry.IsDir:
		return theme.IconRoleDirectory
	default:
		return theme.IconRoleFile
	}
}

// formatScanColumns returns the SENSITIVE, C, H, M, L, SCANNED column values for an entry.
// For git repos: looks up the scan cache directly.
// For directories: aggregates sub-repo scan entries.
func (m *Model) formatScanColumns(entry Entry, frame string) (sensitive secretsCell, c, h, med, l, scanned string) {
	dash := "-"
	empty := ""
	none := secretsCell{}
	unscanned := secretsCell{Text: dash}

	if entry.IsGitRepo {
		if m.scanning(entry.Path) {
			return none, dash, dash, dash, dash, frame + " scanning"
		}
		scanEntry, ok := m.scanCache[entry.Path]
		if !ok {
			return unscanned, dash, dash, dash, dash, dash
		}
		return secretsFor(theme.SecretsVerdict(scanEntry.Sensitive, true)),
			fmt.Sprintf("%d", scanEntry.Critical),
			fmt.Sprintf("%d", scanEntry.High),
			fmt.Sprintf("%d", scanEntry.Medium),
			fmt.Sprintf("%d", scanEntry.Low),
			theme.IconPending + " " + timeAgo(scanEntry.ScannedAt)
	}

	// Files are not scannable — return empty columns
	if !entry.IsDir {
		return none, empty, empty, empty, empty, empty
	}

	// Directory: aggregate sub-repos
	if len(entry.SubRepoPaths) == 0 {
		return secretsFor(theme.SecretsUnknown), empty, empty, empty, empty, empty
	}

	// Count how many sub-repos are currently scanning
	scanningCount := 0
	for _, repoPath := range entry.SubRepoPaths {
		if m.scanning(repoPath) {
			scanningCount++
		}
	}

	var scannedEntries []cache.WorkspaceScanEntry
	for _, repoPath := range entry.SubRepoPaths {
		if e, ok := m.scanCache[repoPath]; ok {
			scannedEntries = append(scannedEntries, e)
		}
	}

	if scanningCount == 0 && len(scannedEntries) == 0 {
		return unscanned, empty, empty, empty, empty, dash
	}
	// A directory with a scan running under it spins, and stops counting.
	//
	// It used to print "3/12" while the batch ran, incremented once per
	// repository — a counter in a six-cell column, at the far right of a row
	// the user is not looking at, for a batch whose progress belongs in the
	// footer. Worse, it was the same cell that says how much of the tree has
	// *ever* been scanned, so the two readings were indistinguishable: 3/12
	// meant "nine left to go" or "nine nobody has scanned", depending on
	// something the cell did not say.
	//
	// Now N/M means one thing — settled coverage — and the batch reports in the
	// footer, where a batch belongs (D9).
	if scanningCount > 0 {
		return none, dash, dash, dash, dash, frame + " scanning"
	}

	totalC, totalH, totalM, totalL := 0, 0, 0, 0
	verdicts := make([]theme.SecretsState, 0, len(scannedEntries))
	for _, e := range scannedEntries {
		totalC += e.Critical
		totalH += e.High
		totalM += e.Medium
		totalL += e.Low
		verdicts = append(verdicts, theme.SecretsVerdict(e.Sensitive, true))
	}

	scannedCount := len(scannedEntries)
	totalCount := len(entry.SubRepoPaths)
	scanned = theme.IconDirectory + " " + fmt.Sprintf("%d/%d", scannedCount, totalCount)

	// The directory only carries the scanned repositories: the ones that are
	// not enter the verdict through the count below, not through a verdict
	// of their own.
	if scannedCount < totalCount {
		verdicts = append(verdicts, theme.SecretsUnknown)
	}

	return secretsFor(foldSecrets(verdicts)),
		fmt.Sprintf("%d", totalC),
		fmt.Sprintf("%d", totalH),
		fmt.Sprintf("%d", totalM),
		fmt.Sprintf("%d", totalL),
		scanned
}

// ciCellFor is the CI grade of one row.
//
// **Only a repository is graded.** A directory aggregates its sub-repositories
// for the severity counters, because counts add up; letters do not — the worst
// of three grades is not the grade of anything, and an average is arithmetic on
// a scale that has none. So a directory shows nothing rather than a number
// nobody could act on.
//
// A repository whose remote is not this context's forge is *unavailable* rather
// than *never scanned*: a dash means "not yet", and this one never will be from
// here (§3.42). The two absences are told apart by the state, never by the
// printed cell.
func (m *Model) ciCellFor(entry Entry) ciCell {
	if !entry.IsGitRepo {
		return ciCell{State: theme.CIScoreUnavailable}
	}
	// GitRemoteURL, not GitRemote: the latter is the display path the Remote
	// column shows (`anthnel/devdesk`), which carries no host at all — a test
	// caught it reading every repository as ungradeable.
	gradeable := git.SameHost(entry.GitRemoteURL, m.config.Forge.URL)
	scanEntry, scanned := m.scanCache[entry.Path]
	if !scanned {
		return ciCell{State: theme.CIScoreVerdict(nil, false, gradeable)}
	}
	return ciCell{
		State: theme.CIScoreVerdict(scanEntry.CIScore, true, gradeable),
		Score: scanEntry.CIScore,
	}
}

// secretsCell is the Secrets column's two halves: what it prints, and the
// verdict that colours it.
//
// The two are not derived from one another. The text has cases the verdict
// does not — a dash for a repository never scanned, nothing at all for a
// file, nothing either during a scan — and those three color the same way,
// dim, because they all say "no verdict".
type secretsCell struct {
	Text  string
	State theme.SecretsState
}

// secretsFor is the cell of a target that has a verdict. Plain text
// (Rule 122): the color goes through Style.
func secretsFor(state theme.SecretsState) secretsCell {
	return secretsCell{Text: theme.SecretsIcon(state), State: state}
}

// foldSecrets is the verdict a directory row carries for the repositories under
// it. A found secret outranks everything; a repository nobody looked at
// outranks "clean", because a parent cannot be more certain than what is
// unknown about its children.
func foldSecrets(states []theme.SecretsState) theme.SecretsState {
	out := theme.SecretsClean
	if len(states) == 0 {
		return theme.SecretsUnknown
	}
	for _, state := range states {
		switch state {
		case theme.SecretsFound:
			return theme.SecretsFound
		case theme.SecretsUnknown:
			out = theme.SecretsUnknown
		}
	}
	return out
}

// timeAgo is a local alias for theme.TimeAgo (Rule 127).
func timeAgo(t time.Time) string { return theme.TimeAgo(t) }

// HeaderView interface implementation

func (m Model) GetShortcuts() shortcut.Shortcuts {
	// Mode input
	if m.mode == ModeAdding {
		return []shortcut.Shortcut{
			{Key: "enter", Description: "Create"},
			{Key: "esc", Description: "Cancel"},
		}
	}

	// Mode renaming
	if m.mode == ModeRenaming {
		return []shortcut.Shortcut{
			{Key: "enter", Description: "Rename"},
			{Key: "esc", Description: "Cancel"},
		}
	}

	// Mode confirm
