package workspaces

import (
	tea "github.com/charmbracelet/bubbletea"

	sharedcomponents "github.com/anthnel/devdesk/internal/ui/components"
	"github.com/anthnel/devdesk/internal/ui/shortcut"
)

// What the selected row and the machine allow, computed once and read by both
// halves of the view: GetShortcuts to gray out, the handlers to refuse.
//
// The defect avoided is the one scan.Categorize and Result.SecretVerdict each
// had to undo: two rules for one question, which eventually stop agreeing.
// Here that would be a grayed-out key that acts anyway — or, worse, an
// offered key whose action returns silently.

// The states come from `shortcut.Availability`: the header and the handler
// read the same field, and it is shared because every view needs it
// (§3.48).
type actionState = shortcut.Availability

// available is the zero-reason state, spelled out where it reads better than an
// empty literal.
var available = actionState{}

// unavailable builds a refused state from the reason to show the user.
func unavailable(reason string) actionState { return shortcut.Unavailable(reason) }

// actionSet is every row-or-machine dependent action of the normal mode.
//
// Three of the view's keys are absent, and for one reason: they apply whatever
// the row is. T and O fall back to the browsed directory when nothing is
// selected, and **N creates a directory in the browsed directory too** — it
// never acts on the selection. Rule 130 used to hide N when a repository was
// selected, which said "this does not apply" about an action that worked
// perfectly; greying it would repeat that, and refusing it would break the
// invariant this file exists for. ctrl+r, /, ctrl+p and ? are likewise
// unconditional.
type actionSet struct {
	Enter  actionState
	Web    actionState
	Scan   actionState
	Sync   actionState
	All    actionState
	Rename actionState
	Delete actionState
	Copy   actionState
}

// The reasons, written once so the header, the footer and the tests cannot
// drift apart on the wording (Rule 129 — English US).
const (
	reasonNoRow        = "No entry selected"
	reasonNotARepo     = "Not a git repository"
	reasonNoScanTarget = "Not a git repository, and no repository nested under it"
	reasonNoRemote     = "This repository has no remote"
	reasonNothingToSee = "Nothing to open — scan this repository first"
	reasonNoScanner    = "No scanner available — install Trivy or Gitleaks, or check scan settings"
)

// reasonUnread is the one refusal that carries a number, and it is a function
// rather than a constant for that reason alone: how many places the walk could
// not look is the whole difference between "there are none" and "I could not
// tell". The other reasons are constants because they say the same thing every
// time (Rule 130).
func reasonUnread(skipped int) string {
	return "No repository found, and " + sharedcomponents.Plural(skipped, "directory", "directories") +
		" could not be read — check logs"
}

// actions works out what applies to the current row on the current machine.
func (m Model) actions() actionSet {
	entry, hasRow := m.selectedEntry()

	a := actionSet{
		Enter:  unavailable(reasonNoRow),
		Web:    unavailable(reasonNoRow),
		Scan:   unavailable(reasonNoRow),
		Sync:   unavailable(reasonNoRow),
		Rename: unavailable(reasonNoRow),
		Delete: unavailable(reasonNoRow),
		Copy:   unavailable(reasonNoRow),
		All:    m.scannerState(),
	}

	if !hasRow {
		// A scan still applies at the root: S falls back to the browsed
		// directory, which is what startSecurityScan does with an empty table.
		a.Scan = m.scannerState()
		return a
	}

	a.Rename = available
	a.Delete = available
	a.Copy = available

	switch {
	case !entry.IsDir:
		// A file opens in the viewer; the other three are a repository's, and
		// they each carry that reason rather than the "no row" one they were
		// initialised with — there *is* a row, it is simply not a repository.
		a.Enter = available
		a.Web = unavailable(reasonNotARepo)
		a.Scan = unavailable(reasonNotARepo)
		a.Sync = unavailable(reasonNotARepo)
	case entry.IsGitRepo:
		if _, scanned := m.scanCache[entry.Path]; scanned {
			a.Enter = available
		} else {
			a.Enter = unavailable(reasonNothingToSee)
		}
		// The browser opens the remote, so a repository without one has
		// nothing to open — IsGitRepo alone advertised W on a local-only clone
		// and openInBrowser then returned in silence.
		if entry.GitRemoteURL != "" {
			a.Web = available
		} else {
			a.Web = unavailable(reasonNoRemote)
		}
		a.Sync = available
		a.Scan = m.scannerState()
	default:
		a.Enter = unavailable(reasonNothingToSee)
		a.Web = unavailable(reasonNotARepo)
		// S and F share one targeting rule: a directory acts on the
		// repositories nested under it, at any depth.
		switch {
		case len(entry.SubRepoPaths) > 0:
			a.Sync = available
			a.Scan = m.scannerState()
		case entry.SubRepoSkipped > 0:
			// Not knowing is not knowing there are none. "No repository nested
			// under it" is a claim the walk is not entitled to make when it
			// could not read part of the tree, and saying it anyway is what
			// made D59 silent rather than merely annoying.
			why := reasonUnread(entry.SubRepoSkipped)
			a.Sync = unavailable(why)
			a.Scan = unavailable(why)
		default:
			a.Sync = unavailable(reasonNoScanTarget)
			a.Scan = unavailable(reasonNoScanTarget)
		}
	}

	return a
}

// guard refuses a key the header shows greyed out, and says why.
//
// The reason is the one actions() computed, so what the footer prints and what
// the header greys can never be about different things. A Warn rather than an
// Error: nothing failed, the action simply does not apply as asked (Rule 128).
func (m Model) guard(s actionState, act func() (tea.Model, tea.Cmd)) (tea.Model, tea.Cmd) {
	if !s.Enabled() {
		return m, m.footer.Warn(s.Reason)
	}
	return act()
}

// scannerState says whether a scan can run at all on this machine.
//
// Not knowing is not knowing that not: while deps is nil the check has not come
// back yet, and greying S out for three frames to un-grey it afterwards reads as
// a fault. One scanner is enough — Trivy and Gitleaks answer different
// questions and either produces a result worth having.
func (m Model) scannerState() actionState {
	if m.deps == nil {
		return available
	}
	if m.deps.TrivyAvailable || m.deps.GitleaksAvailable {
		return available
	}
	return unavailable(reasonNoScanner)
}

package workspaces

import (
	"context"

	"time"

	"github.com/anthnel/devdesk/internal/cache"
	"github.com/anthnel/devdesk/internal/git"
	"github.com/anthnel/devdesk/internal/scan"
)

// DepsCheckedMsg carries where the scanners resolve from on this machine.
//
// It is asked once, from Init: the answer decides whether S and A are offered
// at all, and it cannot be worked out in New or View because resolving a
// scanner shells out (Rule 110).
type DepsCheckedMsg struct {
	Deps scan.DependencyStatus
}

// EntriesLoadedMsg is sent when entries are loaded.
//
// Path is the directory the listing was read from, in the model's own terms —
// "" for the workspaces root. It is what lets Update tell a listing that
// belongs here from one the user has already navigated away from: a load is a
// Cmd, so nothing stops a second navigation from overtaking the first.
type EntriesLoadedMsg struct {
	Path    string
	Entries []Entry
}

// LoadErrorMsg is sent on error. Path carries the same stamp, for the
// same reason: an error about a directory nobody is looking at any more must
// not be reported over the one on screen.
type LoadErrorMsg struct {
	Path  string
	Error error
}

// WorkspaceCreatedMsg is sent when a workspace is created
type WorkspaceCreatedMsg struct {
	Path  string
	Error error
}

// EntryDeletedMsg is sent when an entry is deleted
type EntryDeletedMsg struct {
	Path  string
	Error error
}

// EntryRenamedMsg is sent when an entry is renamed
type EntryRenamedMsg struct {
	OldPath string
	NewPath string
	Error   error
}

// IDEOpenedMsg is sent when the IDE has been opened
type IDEOpenedMsg struct {
	Error error
}

// BrowserOpenedMsg is sent when the default browser has been launched
type BrowserOpenedMsg struct {
	Error error
}

// ScanRequestMsg is sent when user requests a security scan on a directory
type ScanRequestMsg struct {
	TargetPath string
}

// DirectorySelectedMsg is sent when a directory is selected in selection mode
type DirectorySelectedMsg struct {
	Path string
}

// SelectionCancelledMsg is sent when user cancels directory selection
type SelectionCancelledMsg struct{}

// WorkspaceScanStartingMsg is sent when a workspace scan begins for a repo path
type WorkspaceScanStartingMsg struct {
	RepoPath string

	// Cancel stops the scan, and is what makes `K` on this row mean anything
	// (D7). It rides on the starting message because the context is created
	// inside the Cmd: the registry stores it in the same Update that marks the
	// item running, so there is no window where the row is running and cannot
	// be stopped.
	Cancel context.CancelFunc
}

// WorkspaceScanCompleteMsg is sent by the security view when a workspace scan finishes
type WorkspaceScanCompleteMsg struct {
	RepoPath string
	Critical int
	High     int
	Medium   int
	Low      int
	// Sensitive is the secret verdict, nil when no stage looked — the same
	// tri-state the cache entry carries, passed through as-is rather than
	// flattened along the way.
	Sensitive *bool
	// CIScore is the pipeline grade, nil when nobody graded it — carried whole
	// like Sensitive above, and for the same reason: flattening a tri-state on
	// the way is how a "nobody looked" becomes a "nothing found".
	CIScore   *string
	ScannedAt time.Time
	Error     error
}

// WorkspaceSyncStartingMsg is sent when a repository's sync begins
type WorkspaceSyncStartingMsg struct {
	RepoPath string
}

// WorkspaceSyncCompleteMsg is sent when a repository's sync ends, whatever it did.
type WorkspaceSyncCompleteMsg struct {
	RepoPath string
	Outcome  git.SyncOutcome
	Behind   int
	Reason   string
	// Status carries the repository re-read after the sync. Only its git fields
	// are meaningful: it exists so the Git Status column stops describing the
	// state before the fetch, which is the whole point of syncing (D35).
	Status Entry
	Error  error
}

// ScanDetailsRequestMsg is sent when the user wants to view scan details for a repo
type ScanDetailsRequestMsg struct {
	RepoPath string
}

// ScanCacheLoadedMsg is sent when the scan cache has been loaded from disk
type ScanCacheLoadedMsg struct {
	Cache map[string]cache.WorkspaceScanEntry
}

// TerminalExitMsg is sent when the interactive terminal process exits (in-place fallback)
type TerminalExitMsg struct{}

// TerminalOpenedMsg is sent after a non-blocking terminal launch attempt
type TerminalOpenedMsg struct {
	Error error
}

// PathCopiedMsg reports the result of copying the selected entry's path to the
// system clipboard. Path is carried for the log line: a clipboard write fails
// for reasons outside the application (no X selection owner, no pbcopy), and
// naming what it was trying to copy is what makes that report worth reading.
type PathCopiedMsg struct {
	Path  string
	Error error
}
